import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {


  const reactive_energy_consumption = Number(input?.tsl_wo_work_order_attribute?.reactive_energy_consumption ?? 0);
  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || billingItemCode == "null" || billingItemCode == " "  ) {
    return {
      ...input,
        result: {
          rule_description: 'parameter_billingItem_code for rule Contribucion reactiva not found',
          status: 'ERROR',
        }
    };
  };

  // Fuente ÚNICA: arreglo de rangos
  const prices = Array.isArray(input?.graduated_pricing?.prices)
    ? input.graduated_pricing.prices
    : [];

  // Ordena por límite superior ascendente y mapea a {limite, precio}
  const filteredRanges = prices
    .slice()
    .sort(
      (a, b) =>
        Number(a.interval_high ?? 0) -
        Number(b.interval_high ?? 0)
    )
    .map((r) => ({
      limite:
        Number(r.interval_high) === 999999999 ||
        r.interval_high == null
          ? 999999999
          : Number(r.interval_high),
      precio: Number(r.base_price),
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'Rate prices for Contribucion reactiva not found',
        status: 'ERROR',
      }
    };
  }

  if (filteredRanges.length > 0) {
    let costo_total = 0;
    let consumo_restante = reactive_energy_consumption;
    let limite_anterior = 0;

    for (const rango of filteredRanges) {
      if (consumo_restante <= 0) break; // Si ya cubrimos el consumo, terminamos

      let consumo_rango = 0;

      if (rango.limite !== null && rango.limite !== 999999999) {
        consumo_rango = Math.min(consumo_restante, rango.limite - limite_anterior);
      } else {
        consumo_rango = consumo_restante; // Último rango sin límite
      }

      costo_total += consumo_rango * rango.precio;
      consumo_restante -= consumo_rango;
      limite_anterior = rango.limite;
    }

    if ( consumo_restante == 0) {

      const billingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
      const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);

      if (!billingItem) {
        return {
          ...input,
            result: {
              rule_description: 'The parameter_billingItem_code ' + billingItemCode + ' could not be found in the billing concepts structure',
              status: 'ERROR',
            }
        };
      }
      billingItem.billing_item_amount = costo_total;

      return {
        ...input,
        result: {
          total_amount: costo_total,
          status: "OK",
          status_description: "Contribucion reactiva calculation rule completed"
        }
      };
    } else {
      return {
        ...input,
        result: {
          status: "ERROR",
          status_description: "Consumption ranges still need to be calculated"
        }
      };
    }



  } else {
    return {
      ...input,
      result: {
        status_description: "Price structure for Contribucion reactiva is not completed",
        status: "ERROR"
      }
    };
  }


};
